oad = {\\\"items\\\": [1]}\\n        events = []\\n        def first(value):\\n            events.append(\\\"first\\\")\\n            value[\\\"items\\\"].append(2)\\n            return \\\"accepted\\\"\\n        def fail(value):\\n            events.append((\\\"fail\\\", list(value[\\\"items\\\"])))\\n            value[\\\"items\\\"].append(3)\\n            raise ValueError(\\\"invalid payload\\\")\\n        def later(value):\\n            events.append(\\\"later\\\")\\n            return \\\"too late\\\"\\n        try:\\n            dispatch(payload, [first, fail, later])\\n        except ValueError:\\n            pass\\n        self.assertEqual(events, [\\\"first\\\", (\\\"fail\\\", [1])])\\n        self.assertEqual(payload, {\\\"items\\\": [1]})\\n\\n    def test_success_order_results_and_independent_payloads(self):\\n        payload = {\\\"items\\\": [1]}\\n        events = []\\n        received = []\\n        def first(value):\\n            events.append(\\\"first\\\")\\n            received.append(value)\\n            value[\\\"items\\\"].append(2)\\n            return value\\n        def second(value):\\n            events.append(\\\"second\\\")\\n            received.append(value)\\n            self.assertEqual(value, {\\\"items\\\": [1]})\\n            value[\\\"items\\\"].append(3)\\n            return value\\n        self.assertEqual(dispatch(payload, [first, second]),\\n                         [{\\\"items\\\": [1, 2]}, {\\\"items\\\": [1, 3]}])\\n        self.assertEqual(events, [\\\"first\\\", \\\"second\\\"])\\n        self.assertIsNot(received[0], received[1])\\n        self.assertIsNot(received[0][\\\"items\\\"], received[1][\\\"items\\\"])\\n        self.assertEqual(payload, {\\\"items\\\": [1]})\\n\"},\"probe_tests\":[\"-v\",\"test_dispatch\",\"test_dispatch_regression\"],\"guard_project\":true}
